import openpyxl
wb = openpyxl.load_workbook("output/Greenfield_CostBenefit_Analysis.xlsx")
for name in ("Proposal A Model", "Proposal B Model"):
    ws = wb[name]
    print(f"===== {name} =====")
    for r in range(1, ws.max_row + 1):
        vals = [ws.cell(r, c).value for c in range(1, 9)]
        if any(v is not None for v in vals):
            print(r, [str(v)[:55] for v in vals])
EOF", "description": "Dump full content of A and B tabs", "workdir": "/work"}

