{"command": "python3 - <<'EOF'
import openpyxl
wb = openpyxl.load_workbook("output/Greenfield_CostBenefit_Analysis.xlsx")
hits = {"4354518": [], "1168597": [], "1748595": [], "9.56": [], "941951": [], "453292": [], "388800": []}
for ws in wb:
    for row in ws.iter_rows():
        for c in row:
            if c.value is None:
                continue
            s = str(c.value)
            for k in hits:
                if k in s.replace(",", ""):
                    hits[k].append((ws.title, c.coordinate, s[:60]))
for k, v in hits.items():
    print(k, "->", v[:3] if v else "NOT FOUND")
EOF", "description": "Verify numeric presence of key figures in workbook", "workdir": "/work"}

