    ws = wb[name]
    print(f"\n=== {name}: {ws.max_row} rows x {ws.max_column} cols ===")
    cf_rules = []
    for rng, rules in ws.conditional_formatting._cf_rules.items():
        for rule in rules:
            cf_rules.append((str(rng.sqref), rule.type, rule.operator, rule.formula if hasattr(rule,'formula') else None))
    if cf_rules:
        print("  Conditional formatting:", cf_rules)
